BEGIN;
CREATE TABLE IF NOT EXISTS hollowgate_vtt.campaign_documents(campaign_id uuid NOT NULL REFERENCES hollowgate_vtt.campaigns(id) ON DELETE CASCADE,document_key text NOT NULL CHECK(document_key IN ('map','phases','combat','active-encounter','map-placements','map-grids','map-tokens','map-drawings','map-pois','map-fog','map-object-orders')),payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(campaign_id,document_key));
ALTER TABLE hollowgate_vtt.campaign_documents DROP CONSTRAINT IF EXISTS campaign_documents_document_key_check;
ALTER TABLE hollowgate_vtt.campaign_documents ADD CONSTRAINT campaign_documents_document_key_check CHECK(document_key IN ('map','phases','combat','active-encounter','map-placements','map-grids','map-tokens','map-drawings','map-pois','map-fog','map-object-orders'));
REVOKE ALL ON hollowgate_vtt.campaign_documents FROM PUBLIC,hollowgate_api_runtime;
CREATE OR REPLACE FUNCTION hollowgate_vtt.campaign_document_owner_authorized(p_owner uuid,p_campaign uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM hollowgate_vtt.campaigns c JOIN hollowgate_auth.users u ON u.id=c.owner_id WHERE c.id=p_campaign AND c.owner_id=p_owner AND u.status='active' AND u.email_verified_at IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION hollowgate_vtt.read_owned_campaign_document(p_owner uuid,p_campaign uuid,p_key text) RETURNS TABLE(payload jsonb) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT d.payload FROM hollowgate_vtt.campaign_documents d WHERE d.campaign_id=p_campaign AND d.document_key=p_key AND hollowgate_vtt.campaign_document_owner_authorized(p_owner,p_campaign) $$;
CREATE OR REPLACE FUNCTION hollowgate_vtt.save_owned_campaign_document(p_owner uuid,p_campaign uuid,p_key text,p_payload jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN IF NOT hollowgate_vtt.campaign_document_owner_authorized(p_owner,p_campaign) OR p_payload IS NULL OR p_key NOT IN ('map','phases','combat','active-encounter','map-placements','map-grids','map-tokens','map-drawings','map-pois','map-fog','map-object-orders') THEN RETURN false; END IF; INSERT INTO hollowgate_vtt.campaign_documents(campaign_id,document_key,payload) VALUES(p_campaign,p_key,p_payload) ON CONFLICT(campaign_id,document_key) DO UPDATE SET payload=EXCLUDED.payload,updated_at=now(); RETURN true; END $$;
CREATE OR REPLACE FUNCTION hollowgate_vtt.delete_owned_campaign_document(p_owner uuid,p_campaign uuid,p_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN IF NOT hollowgate_vtt.campaign_document_owner_authorized(p_owner,p_campaign) THEN RETURN false; END IF; DELETE FROM hollowgate_vtt.campaign_documents WHERE campaign_id=p_campaign AND document_key=p_key; RETURN true; END $$;
REVOKE ALL ON FUNCTION hollowgate_vtt.campaign_document_owner_authorized(uuid,uuid),hollowgate_vtt.read_owned_campaign_document(uuid,uuid,text),hollowgate_vtt.save_owned_campaign_document(uuid,uuid,text,jsonb),hollowgate_vtt.delete_owned_campaign_document(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION hollowgate_vtt.campaign_document_owner_authorized(uuid,uuid),hollowgate_vtt.read_owned_campaign_document(uuid,uuid,text),hollowgate_vtt.save_owned_campaign_document(uuid,uuid,text,jsonb),hollowgate_vtt.delete_owned_campaign_document(uuid,uuid,text) TO hollowgate_api_runtime;
COMMIT;
